protected RetailLoyaltyCard getTableRecord(Common _pricingObject)
{
    SalesTable   salesTable = _pricingObject as SalesTable;
    RetailLoyaltyCard retailLoyaltyCard;

    if (salesTable)
    {
        retailLoyaltyCard = RetailLoyaltyCard::find(salesTable.retailSalesTable().RetailLoyaltyCard);
    }

    return retailLoyaltyCard;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbdsRoot;

    if (_qbdsMap && _qbdsMap.exists(tableStr(RetailLoyaltyCard)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(RetailLoyaltyCard));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(RetailLoyaltyCard));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(RetailLoyaltyCard), qbdsRoot);
        }
    }

    return qbdsRoot;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}
